/* ============================================================
   Логика
   ============================================================ */

/* Имя файла и путь в нижнем регистре.
   Путь берём через fsName (обычный путь Windows, без %-кодов)
   и приводим разделители к «/».
   Если документ не сохранён — вернутся пустые строки. */
function getDocInfo(doc) {
    var info = { name: "", path: "" };
    try { info.name = String(doc.name).toLowerCase(); } catch (e) {}
    try {
        info.path = String(doc.path.fsName).replace(/\\/g, "/").toLowerCase();
    } catch (e) {}
    return info;
}


/* Размер документа в см. ppi не задан — по разрешению самого документа,
   задан — как если бы у документа было такое разрешение. */
function docSizeCm(doc, ppi) {
    var w = doc.width.as("cm");
    var h = doc.height.as("cm");
    if (ppi) {
        var k = doc.resolution / ppi;
        w *= k;
        h *= k;
    }
    return { w: w, h: h };
}


/* Все форматы, подходящие по размеру */
function candidatesBySize(doc, ppi) {
    var size = docSizeCm(doc, ppi);
    var w = size.w;
    var h = size.h;
    var docShort = Math.min(w, h);
    var docLong  = Math.max(w, h);
    var out = [];

    for (var i = 0; i < FORMATS.length; i++) {
        var f = FORMATS[i];
        var fShort = Math.min(f.w, f.h);
        var fLong  = Math.max(f.w, f.h);
        if (Math.abs(docShort - fShort) <= TOLERANCE_CM &&
            Math.abs(docLong  - fLong)  <= TOLERANCE_CM) {
            out.push(f);
        }
    }
    return out;
}


/* Насколько формат подходит по имени файла и папке.
   2 — совпало ключевое слово в имени
   1 — слово из folders есть в названии одной из папок пути
   0 — признаков нет */
function score(f, info) {
    var i, j;
    if (f.keywords) {
        for (i = 0; i < f.keywords.length; i++) {
            if (info.name.indexOf(f.keywords[i]) !== -1) return 2;
        }
    }
    if (f.folders) {
        var parts = info.path.split("/");
        for (i = 0; i < f.folders.length; i++) {
            for (j = 0; j < parts.length; j++) {
                if (parts[j].indexOf(f.folders[i]) !== -1) return 1;
            }
        }
    }
    return 0;
}


function pickFormat(doc, ppi) {
    var list = candidatesBySize(doc, ppi);

    if (list.length === 0) return null;
    if (list.length === 1) return list[0];

    /* Несколько кандидатов по размеру (случай 10x15).
       Смотрим на имя файла и папку: если совпало ключевое
       слово или папка — берём этот формат.
       Если не совпало ничего — значит обычный формат,
       то есть первый в таблице без ключевых слов. */

    var info = getDocInfo(doc);
    var i, best = null, bestScore = 0;

    for (i = 0; i < list.length; i++) {
        var s = score(list[i], info);
        if (s > bestScore) { bestScore = s; best = list[i]; }
    }
    if (best !== null) return best;

    // признаков нет — берём формат по умолчанию
    for (i = 0; i < list.length; i++) {
        if (!list[i].keywords && !list[i].folders) return list[i];
    }
    return list[0];
}


/* Формат документа и разрешение, с которым его печатать.
   null — не распознан. */
function detect(doc) {
    var fmt = pickFormat(doc, null);
    if (fmt) return { fmt: fmt, ppi: doc.resolution };

    for (var i = 0; i < PPI_GUESSES.length; i++) {
        if (Math.abs(PPI_GUESSES[i] - doc.resolution) < 1) continue;
        fmt = pickFormat(doc, PPI_GUESSES[i]);
        if (fmt) return { fmt: fmt, ppi: PPI_GUESSES[i] };
    }
    return null;
}


function sizeText(doc) {
    var px = function (v) { return Math.round(v.as("cm") / 2.54 * doc.resolution); };
    return doc.width.as("cm").toFixed(1) + " x " +
           doc.height.as("cm").toFixed(1) + " \u0441\u043c  (" +            // см
           px(doc.width) + " x " + px(doc.height) + " px, " +
           Math.round(doc.resolution) + " ppi)";
}


/* ---------- Настройки этого компа ---------- */

function settingsFile(f) {
    return new File(SETTINGS_DIR + "/" + f.id + ".desc");
}

/* Сохранённые настройки формата или null */
function loadSaved(f) {
    var file = settingsFile(f);
    if (!file.exists) return null;
    try {
        file.encoding = "BINARY";
        if (!file.open("r")) return null;
        var data = file.read();
        file.close();
        var d = new ActionDescriptor();
        d.fromStream(data);
        return d;
    } catch (e) {
        try { file.close(); } catch (e2) {}
        return null;
    }
}

function saveSettings(f, d) {
    var dir = new Folder(SETTINGS_DIR);
    if (!dir.exists) dir.create();
    var file = settingsFile(f);
    file.encoding = "BINARY";
    if (!file.open("w")) throw new Error("Не удалось записать " + file.fsName);
    file.write(d.toStream());
    file.close();
}

/* Команда печати должна ссылаться на текущий документ */
function ensureTarget(d) {
    var idnull = charIDToTypeID("null");
    if (d.hasKey(idnull)) return d;
    var ref = new ActionReference();
    ref.putProperty(charIDToTypeID("Prpr"), stringIDToTypeID("printOutput"));
    ref.putEnumerated(charIDToTypeID("Dcmn"), charIDToTypeID("Ordn"), charIDToTypeID("Trgt"));
    d.putReference(idnull, ref);
    return d;
}

/* Печать в настоящем размере: масштаб 100% и разрешение — как у документа.
   В записанных настройках разрешение зашито (500 ppi — как у шаблонов на
   первой точке). Если у документа другое, Photoshop при печати подменял
   разрешение документа, и A5 300 ppi печатался 12.6x8.9 см. */
function fitToDocument(d, ppi) {
    var key = stringIDToTypeID("printOutputOptions");
    if (!d.hasKey(key)) return d;
    var cls = d.getObjectType(key);
    var opt = d.getObjectValue(key);
    opt.putUnitDouble(charIDToTypeID("Rslt"), charIDToTypeID("#Pxl"), ppi);
    opt.putUnitDouble(charIDToTypeID("Scl "), charIDToTypeID("#Prc"), 100);
    d.putObject(key, cls, opt);
    return d;
}

/* Принтер, на который настроен этот комп (по любому настроенному формату),
   или null, если ничего не настроено */
function localPrinter() {
    for (var i = 0; i < FORMATS.length; i++) {
        var d = loadSaved(FORMATS[i]);
        if (!d) continue;
        try {
            return d.getObjectValue(stringIDToTypeID("printOutput"))
                    .getString(stringIDToTypeID("printerName"));
        } catch (e) {}
    }
    return null;
}

function doPrint(d, ppi) {
    executeAction(charIDToTypeID("Prnt"), fitToDocument(ensureTarget(d), ppi), DialogModes.NO);
    executeAction(stringIDToTypeID("printOneCopy"), undefined, DialogModes.NO);
}


/* ---------- Печать (основная кнопка) ---------- */

function main() {

    if (app.documents.length === 0) {
        alert("Нет открытого документа.");
        return;
    }

    var doc = app.activeDocument;
    var found = detect(doc);
    var fmt = found ? found.fmt : null;
    var saved = fmt ? loadSaved(fmt) : null;

    if (DEBUG) {
        var info = getDocInfo(doc);
        alert("DEBUG\n\n" +
              "Размер: " + sizeText(doc) + "\n" +
              "Имя: " + info.name + "\n" +
              "Папка: " + info.path + "\n\n" +
              "Выбран формат: " + (fmt ? fmt.name : "— не распознан —") + "\n" +
              (found ? "Печать с разрешением: " + Math.round(found.ppi) + " ppi\n" : "") +
              "Настройки: " + (saved ? "этого компа" : "встроенные") +
              "\n\n(печать в режиме DEBUG не запускается)");
        return;
    }

    if (fmt === null) {
        alert("Формат не распознан.\n\nРазмер документа: " + sizeText(doc) +
              "\n\nОжидается 10x15, A5, A4 или A3 (допуск " + TOLERANCE_CM + " см).");
        return;
    }

    // встроенные настройки сняты с EPSON L18050: на другом принтере
    // (например L8050) им верить нельзя — как и своей бумаге (customPaper)
    var other = saved === null ? localPrinter() : null;
    var foreign = other !== null && other !== PRINTER_NAME;

    if (saved === null && (fmt.customPaper || foreign)) {
        if (!confirm("Формат «" + fmt.name + "» на этом компе ещё не настроен.\n\n" +
                     "Запустите File -> Scripts -> Print_ByFormat_Setup,\n" +
                     "иначе бумага может выбраться не та.\n\n" +
                     "Всё равно печатать встроенными настройками?")) return;
    } else if (CONFIRM_BEFORE_PRINT) {
        if (!confirm("Формат: " + fmt.name + "\n\nПечатать?")) return;
    }

    try {
        doPrint(saved !== null ? saved : fmt.desc(), found.ppi);
    } catch (e) {
        alert("Ошибка при печати.\n\nФормат: " + fmt.name +
              "\nНастройки: " + (saved ? "этого компа" : "встроенные") + "\n\n" + e);
    }
}


/* ---------- Настройка (кнопка Print_ByFormat_Setup) ---------- */

function setupStatus() {
    var lines = [];
    for (var i = 0; i < FORMATS.length; i++) {
        var f = FORMATS[i];
        lines.push((settingsFile(f).exists ? "[+] " : "[  ] ") + f.name);
    }
    return lines.join("\n");
}

function setup() {

    if (app.documents.length === 0) {
        alert("НАСТРОЙКА ПЕЧАТИ\n\n" +
              "Откройте шаблон нужного формата и запустите Настройку ещё раз.\n\n" +
              "Настроено на этом компе:\n" + setupStatus());
        return;
    }

    var doc = app.activeDocument;
    var found = detect(doc);
    var fmt = found ? found.fmt : null;

    if (fmt === null) {
        alert("Формат не распознан.\n\nРазмер документа: " + sizeText(doc) +
              "\n\nОткройте шаблон 10x15, A5, A4 или A3.");
        return;
    }

    var saved = loadSaved(fmt);

    if (!confirm("НАСТРОЙКА: " + fmt.name +
                 (saved ? "  (уже настроен — перенастроить)" : "") + "\n\n" +
                 "Сейчас откроется окно печати.\n" +
                 "1. Принтер — EPSON, профиль — как обычно.\n" +
                 "2. «Параметры печати» -> выберите бумагу для этого\n" +
                 "   формата (как она называется на этой точке),\n" +
                 "   без полей, тип бумаги, качество -> OK.\n" +
                 "3. Нажмите «Готово».\n\n" +
                 "Продолжить?")) return;

    var result;
    try {
        result = executeAction(charIDToTypeID("Prnt"),
                               fitToDocument(ensureTarget(saved !== null ? saved : fmt.desc()), found.ppi),
                               DialogModes.ALL);
    } catch (e) {
        alert("Настройка не сохранена (окно закрыто без «Готово»).\n\n" +
              "Если «Готово» не срабатывает — попробуйте ещё раз\n" +
              "и нажмите «Печать» (будет одна пробная печать).\n\n" + e);
        return;
    }

    if (!result || !result.hasKey(stringIDToTypeID("osSpecificPrintInfo"))) {
        alert("Photoshop не вернул настройки драйвера — сохранить нечего.\n" +
              "Пришлите это сообщение тому, кто настраивал скрипт.");
        return;
    }

    try {
        saveSettings(fmt, ensureTarget(result));
    } catch (e) {
        alert("Ошибка сохранения настроек.\n\n" + e);
        return;
    }

    alert("Готово: «" + fmt.name + "» настроен на этом компе.\n\n" +
          "Настроено:\n" + setupStatus());
}


/* Print_ByFormat_Setup.jsx ставит PBF_SETUP_MODE = true и запускает этот файл */
if (typeof PBF_SETUP_MODE !== "undefined" && PBF_SETUP_MODE) setup();
else main();
